ALTER TABLE public.audit_requests ADD COLUMN IF NOT EXISTS website text, ADD COLUMN IF NOT EXISTS social_media text, ADD COLUMN IF NOT EXISTS profile_screenshots jsonb NOT NULL DEFAULT '[]'::jsonb;
UPDATE public.audit_requests SET website = (SELECT entry->>'link' FROM jsonb_array_elements(COALESCE(online_links, '[]'::jsonb)) entry WHERE entry->>'platform' = 'Website' LIMIT 1), social_media = (SELECT string_agg(CASE WHEN entry->>'platform' = 'Other' THEN COALESCE(entry->>'other_name', 'Other') ELSE entry->>'platform' END || ': ' || (entry->>'link'), E'\n') FROM jsonb_array_elements(COALESCE(online_links, '[]'::jsonb)) entry WHERE entry->>'platform' <> 'Website') WHERE website IS NULL AND social_media IS NULL;
COMMENT ON COLUMN public.audit_requests.online_links IS 'DEPRECATED: new submissions use website, social_media and profile_screenshots; retained for historical profile screenshot readback.';